-- CengiSalas / Supabase
-- 20: solicitudes externas comerciales con cotización y bloqueo provisional.

do $$
begin
  alter type public.room_block_type add value if not exists 'payment_hold';
exception when duplicate_object then null;
end $$;

commit;

begin;

alter table public.meetings add column if not exists paid_offering_code text;
alter table public.meetings add column if not exists quoted_amount numeric(12,2);
alter table public.meetings add column if not exists payment_status text not null default 'pending';
alter table public.meetings drop constraint if exists meetings_request_source_check;
alter table public.meetings drop constraint if exists meetings_request_source_check1;
alter table public.meetings add constraint meetings_request_source_check check(request_source in ('registered','public','paid'));
alter table public.meetings add constraint meetings_quoted_amount_nonnegative check(quoted_amount is null or quoted_amount>=0);
alter table public.meetings add constraint meetings_payment_status_check check(payment_status in ('pending','quoted','paid','cancelled'));

do $$
declare c record;
begin
  for c in select conname from pg_constraint where conrelid='public.room_blocks'::regclass and pg_get_constraintdef(oid) like '%block_type%'
  loop execute format('alter table public.room_blocks drop constraint %I',c.conname); end loop;
end $$;
alter table public.room_blocks add constraint room_blocks_type_check check(
  (block_type in ('meeting','payment_hold') and occurrence_id is not null and maintenance_id is null)
  or (block_type='maintenance' and maintenance_id is not null and occurrence_id is null)
);

create table if not exists public.paid_space_offerings(
  id bigint generated by default as identity primary key,
  code text not null unique check(code in ('MAIN_HALL','TRAINING_HALL','EXECUTIVE_HALL')),
  name text not null,
  description text,
  allocation_mode text not null check(allocation_mode in ('combined','either','single')),
  capacities jsonb not null default '{}'::jsonb,
  price_one_hour numeric(12,2) not null default 0 check(price_one_hour>=0),
  price_four_to_eight_hours numeric(12,2) not null default 0 check(price_four_to_eight_hours>=0),
  price_extra_hour_after_eight numeric(12,2) not null default 0 check(price_extra_hour_after_eight>=0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.paid_space_offerings enable row level security;
grant select on public.paid_space_offerings to anon,authenticated;
drop policy if exists paid_offerings_read on public.paid_space_offerings;
create policy paid_offerings_read on public.paid_space_offerings for select to anon,authenticated using(is_active or private.is_admin());

insert into public.paid_space_offerings(code,name,description,allocation_mode,capacities,price_one_hour,price_four_to_eight_hours,price_extra_hour_after_eight)
select 'MAIN_HALL','Salón principal','Salones 1 y 2 combinados para eventos de mayor capacidad.','combined',coalesce((select jsonb_object_agg(ct.code,sc.capacity) from public.space_capacities sc join public.configuration_types ct on ct.id=sc.configuration_type_id where sc.space_id=s.id),'{}'::jsonb),coalesce((select r.cost_one_hour from public.rooms r where r.code='ROOM_1'),0)+coalesce((select r.cost_one_hour from public.rooms r where r.code='ROOM_2'),0),coalesce((select r.cost_four_to_eight_hours from public.rooms r where r.code='ROOM_1'),0)+coalesce((select r.cost_four_to_eight_hours from public.rooms r where r.code='ROOM_2'),0),coalesce((select r.cost_extra_hour_after_eight from public.rooms r where r.code='ROOM_1'),0)+coalesce((select r.cost_extra_hour_after_eight from public.rooms r where r.code='ROOM_2'),0)
from public.spaces s where s.code='SPACE_1_2' on conflict(code) do nothing;
insert into public.paid_space_offerings(code,name,description,allocation_mode,capacities,price_one_hour,price_four_to_eight_hours,price_extra_hour_after_eight)
select
  'TRAINING_HALL',
  'Salón de Formación',
  'Salón 1 o Salón 2 según disponibilidad.',
  'either',
  jsonb_build_object(
    'U', coalesce((select max(sc.capacity) from public.space_capacities sc join public.spaces s on s.id=sc.space_id join public.configuration_types ct on ct.id=sc.configuration_type_id where s.code in ('SPACE_1','SPACE_2') and ct.code='U'),0),
    'SCHOOL', coalesce((select max(sc.capacity) from public.space_capacities sc join public.spaces s on s.id=sc.space_id join public.configuration_types ct on ct.id=sc.configuration_type_id where s.code in ('SPACE_1','SPACE_2') and ct.code='SCHOOL'),0)
  ),
  coalesce((select max(r.cost_one_hour) from public.rooms r where r.code in ('ROOM_1','ROOM_2')),0),
  coalesce((select max(r.cost_four_to_eight_hours) from public.rooms r where r.code in ('ROOM_1','ROOM_2')),0),
  coalesce((select max(r.cost_extra_hour_after_eight) from public.rooms r where r.code in ('ROOM_1','ROOM_2')),0)
on conflict(code) do nothing;

insert into public.paid_space_offerings(code,name,description,allocation_mode,capacities,price_one_hour,price_four_to_eight_hours,price_extra_hour_after_eight)
select 'EXECUTIVE_HALL','Salón Ejecutivo','Salón 3 para reuniones ejecutivas de hasta 15 personas.','single',coalesce((select jsonb_object_agg(ct.code,sc.capacity) from public.space_capacities sc join public.configuration_types ct on ct.id=sc.configuration_type_id where sc.space_id=s.id),'{}'::jsonb),coalesce((select r.cost_one_hour from public.rooms r where r.code='ROOM_3'),0),coalesce((select r.cost_four_to_eight_hours from public.rooms r where r.code='ROOM_3'),0),coalesce((select r.cost_extra_hour_after_eight from public.rooms r where r.code='ROOM_3'),0)
from public.spaces s where s.code='SPACE_3' on conflict(code) do nothing;

create or replace function public.get_paid_request_catalogs()
returns jsonb language sql stable security definer set search_path='' as $$
select jsonb_build_object('organizations',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'code',o.code,'name',o.name) order by o.name) from public.organizations o where o.is_active),'[]'::jsonb),'meetingTypes',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'code',m.code,'name',m.name) order by m.id) from public.meeting_types m where m.is_active),'[]'::jsonb),'configurations',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'code',c.code,'name',c.name,'description',c.description) order by c.id) from public.configuration_types c where c.is_active),'[]'::jsonb),'offerings',coalesce((select jsonb_agg(to_jsonb(p) order by p.id) from public.paid_space_offerings p where p.is_active),'[]'::jsonb));
$$;

create or replace function private.release_payment_hold_before_meeting_block()
returns trigger language plpgsql set search_path='' as $$
begin
  if new.block_type='meeting' and new.occurrence_id is not null then update public.room_blocks set active=false where occurrence_id=new.occurrence_id and block_type='payment_hold' and active; end if;
  return new;
end;
$$;
drop trigger if exists release_payment_hold_before_meeting_block on public.room_blocks;
create trigger release_payment_hold_before_meeting_block before insert on public.room_blocks for each row execute function private.release_payment_hold_before_meeting_block();

create or replace function public.admin_update_paid_offering(p_offering_id bigint,p_name text,p_description text,p_capacities jsonb,p_price_one_hour numeric,p_price_four_to_eight_hours numeric,p_price_extra_hour_after_eight numeric)
returns void language plpgsql security definer set search_path='' as $$
begin
  perform private.require_admin();
  if nullif(btrim(p_name),'') is null or p_price_one_hour<0 or p_price_four_to_eight_hours<0 or p_price_extra_hour_after_eight<0 then raise exception 'Nombre y precios inválidos.'; end if;
  update public.paid_space_offerings set name=btrim(p_name),description=nullif(btrim(p_description),''),capacities=p_capacities,price_one_hour=p_price_one_hour,price_four_to_eight_hours=p_price_four_to_eight_hours,price_extra_hour_after_eight=p_price_extra_hour_after_eight where id=p_offering_id and is_active;
  if not found then raise exception 'Oferta comercial no encontrada.'; end if;
end;
$$;

create or replace function public.create_paid_meeting_request(
  p_contact_name text,p_contact_email text,p_contact_phone text,p_organization_id bigint,
  p_offering_code text,p_title text,p_description text,p_meeting_type_id bigint,p_configuration_type_id bigint,p_attendees integer,
  p_occurrences jsonb,p_recurrence_type public.recurrence_type default 'none',p_recurrence_end_date date default null,
  p_observations text default null,p_website text default null
)
returns text language plpgsql security definer set search_path='' as $$
declare v_id uuid:=gen_random_uuid();v_code text;v_offering public.paid_space_offerings%rowtype;v_item jsonb;v_space_id bigint;v_occ_id uuid;v_quote numeric:=0;v_hours numeric;v_config_code text;
begin
  if nullif(btrim(p_website),'') is not null then raise exception 'No fue posible procesar la solicitud.'; end if;
  select * into strict v_offering from public.paid_space_offerings where code=upper(btrim(p_offering_code)) and is_active;
  select code into strict v_config_code from public.configuration_types where id=p_configuration_type_id and is_active;
  if p_occurrences is null or jsonb_typeof(p_occurrences)<>'array' or jsonb_array_length(p_occurrences)<1 or jsonb_array_length(p_occurrences)>100 then raise exception 'Las fechas son inválidas.'; end if;
  if p_recurrence_type='none' and jsonb_array_length(p_occurrences)<>1 then raise exception 'Una reunión no recurrente debe contener una fecha.'; end if;
  if p_recurrence_type<>'none' and jsonb_array_length(p_occurrences)<2 then raise exception 'Una reunión recurrente debe contener al menos dos fechas.'; end if;
  if not exists(select 1 from public.organizations where id=p_organization_id and is_active) then raise exception 'Organización inválida.'; end if;
  if not exists(select 1 from public.meeting_types where id=p_meeting_type_id and is_active) then raise exception 'Tipo de reunión inválido.'; end if;
  if p_attendees is null or p_attendees<=0 then raise exception 'La cantidad de asistentes debe ser mayor que cero.'; end if;
  if coalesce((v_offering.capacities->>v_config_code)::integer,0)<p_attendees then raise exception 'La capacidad del espacio comercial es insuficiente.'; end if;
  if nullif(btrim(p_contact_name),'') is null or nullif(btrim(p_contact_email),'') is null or nullif(btrim(p_contact_phone),'') is null then raise exception 'Completa los datos de contacto.'; end if;

  for v_item in select value from jsonb_array_elements(p_occurrences) loop
    if v_offering.allocation_mode='combined' then select id into strict v_space_id from public.spaces where code='SPACE_1_2' and is_active;
    elsif v_offering.allocation_mode='single' then select id into strict v_space_id from public.spaces where code='SPACE_3' and is_active;
    else select s.id into v_space_id from public.spaces s where s.code in ('SPACE_1','SPACE_2') and s.is_active and private.space_is_available(s.id,(v_item->>'starts_at')::timestamptz,(v_item->>'ends_at')::timestamptz,null) and exists(select 1 from public.space_capacities sc join public.configuration_types c on c.id=sc.configuration_type_id where sc.space_id=s.id and c.code=v_config_code and sc.capacity>=p_attendees) order by case when s.code='SPACE_1' then 1 else 2 end limit 1; if v_space_id is null then raise exception 'Los salones de formación no están disponibles en una de las fechas.'; end if; end if;
    perform private.validate_space_capacity(v_space_id,p_configuration_type_id,p_attendees);
    if not private.space_is_available(v_space_id,(v_item->>'starts_at')::timestamptz,(v_item->>'ends_at')::timestamptz,null) then raise exception 'El espacio solicitado ya está ocupado en una de las fechas.'; end if;
    v_hours:=extract(epoch from ((v_item->>'ends_at')::timestamptz-(v_item->>'starts_at')::timestamptz))/3600;
    v_quote:=v_quote+case when v_hours<=3 then v_offering.price_one_hour*v_hours when v_hours<=8 then v_offering.price_four_to_eight_hours else v_offering.price_four_to_eight_hours+(v_hours-8)*v_offering.price_extra_hour_after_eight end;
  end loop;
  v_code:=private.generate_request_code();
  insert into public.meetings(id,request_code,requester_name,requester_email,request_organization_id,meeting_type_id,configuration_type_id,title,description,observations,attendees,recurrence_type,recurrence_end_date,contact_name,contact_email,contact_phone,request_source,paid_offering_code,quoted_amount,payment_status)
  values(v_id,v_code,btrim(p_contact_name),lower(btrim(p_contact_email)),p_organization_id,p_meeting_type_id,p_configuration_type_id,btrim(p_title),nullif(btrim(p_description),''),nullif(btrim(p_observations),''),p_attendees,p_recurrence_type,p_recurrence_end_date,btrim(p_contact_name),lower(btrim(p_contact_email)),btrim(p_contact_phone),'paid',v_offering.code,round(v_quote,2),'quoted');
  for v_item in select value from jsonb_array_elements(p_occurrences) loop
    if v_offering.allocation_mode='combined' then select id into strict v_space_id from public.spaces where code='SPACE_1_2' and is_active;
    elsif v_offering.allocation_mode='single' then select id into strict v_space_id from public.spaces where code='SPACE_3' and is_active;
    else select s.id into strict v_space_id from public.spaces s where s.code in ('SPACE_1','SPACE_2') and s.is_active and private.space_is_available(s.id,(v_item->>'starts_at')::timestamptz,(v_item->>'ends_at')::timestamptz,null) and exists(select 1 from public.space_capacities sc join public.configuration_types c on c.id=sc.configuration_type_id where sc.space_id=s.id and c.code=v_config_code and sc.capacity>=p_attendees) order by case when s.code='SPACE_1' then 1 else 2 end limit 1; end if;
    v_occ_id:=gen_random_uuid();
    insert into public.meeting_occurrences(id,meeting_id,space_id,starts_at,ends_at) values(v_occ_id,v_id,v_space_id,(v_item->>'starts_at')::timestamptz,(v_item->>'ends_at')::timestamptz);
    insert into public.meeting_occurrence_status_history(occurrence_id,to_status,reason,actor_name,actor_role) values(v_occ_id,'pending','Solicitud externa comercial creada',btrim(p_contact_name),'user');
    insert into public.room_blocks(room_id,occurrence_id,block_type,starts_at,ends_at) select sr.room_id,v_occ_id,'payment_hold',(v_item->>'starts_at')::timestamptz,(v_item->>'ends_at')::timestamptz from public.space_rooms sr where sr.space_id=v_space_id;
  end loop;
  insert into public.audit_log(actor_role,action,entity_type,entity_id,new_data) values('user','create_paid_request','meeting',v_id::text,jsonb_build_object('request_code',v_code,'quoted_amount',round(v_quote,2)));
  insert into public.board_events(event_type,entity_type,entity_id) values('request','meeting',v_id::text);
  return v_code;
end;
$$;

drop view if exists public.vw_request_occurrences;
create view public.vw_request_occurrences with(security_invoker=true) as
select o.id occurrence_id,m.id meeting_id,m.request_code,m.title,m.description,m.requested_by,m.requester_name,m.requester_email,org.name organization_name,d.name department_name,mt.name meeting_type_name,ct.name configuration_name,m.attendees,m.recurrence_type,m.recurrence_end_date,s.id space_id,s.name space_name,o.starts_at,o.ends_at,o.status,o.created_at requested_at,approved.changed_at approved_at,rejected.changed_at rejected_at,rejected.reason rejection_reason,rejected.actor_name rejected_by_name,cancelled.changed_at cancelled_at,cancelled.reason cancellation_reason,cancelled.actor_role cancelled_by_role,cancelled.actor_name cancelled_by_name,moved.changed_at last_moved_at,old_space.name previous_space_name,moved.reason movement_reason,rescheduled.changed_at last_rescheduled_at,m.contact_name,m.contact_email,m.contact_phone,m.request_source,m.observations,m.paid_offering_code,m.quoted_amount,m.payment_status
from public.meeting_occurrences o join public.meetings m on m.id=o.meeting_id join public.organizations org on org.id=m.request_organization_id left join public.departments d on d.id=m.request_department_id join public.meeting_types mt on mt.id=m.meeting_type_id join public.configuration_types ct on ct.id=m.configuration_type_id join public.spaces s on s.id=o.space_id
left join lateral(select h.changed_at from public.meeting_occurrence_status_history h where h.occurrence_id=o.id and h.to_status='approved' order by h.changed_at desc limit 1) approved on true
left join lateral(select h.changed_at,h.reason,h.actor_name from public.meeting_occurrence_status_history h where h.occurrence_id=o.id and h.to_status='rejected' order by h.changed_at desc limit 1) rejected on true
left join lateral(select h.changed_at,h.reason,h.actor_role,h.actor_name from public.meeting_occurrence_status_history h where h.occurrence_id=o.id and h.to_status='cancelled' order by h.changed_at desc limit 1) cancelled on true
left join lateral(select sh.old_space_id,sh.changed_at,sh.reason from public.meeting_occurrence_space_history sh where sh.occurrence_id=o.id and sh.old_space_id is not null order by sh.changed_at desc limit 1) moved on true
left join lateral(select a.created_at changed_at from public.audit_log a where a.entity_type='meeting_occurrence' and a.entity_id=o.id::text and a.action='reschedule' order by a.created_at desc limit 1) rescheduled on true left join public.spaces old_space on old_space.id=moved.old_space_id;
revoke all on public.vw_request_occurrences from public,anon,authenticated;
grant select on public.vw_request_occurrences to authenticated;

revoke all on function public.get_paid_request_catalogs() from public,anon,authenticated;
revoke all on function public.create_paid_meeting_request(text,text,text,bigint,text,text,text,bigint,bigint,integer,jsonb,public.recurrence_type,date,text,text) from public,anon,authenticated;
revoke all on function public.admin_update_paid_offering(bigint,text,text,jsonb,numeric,numeric,numeric) from public,anon,authenticated;
grant execute on function public.get_paid_request_catalogs() to anon,authenticated;
grant execute on function public.create_paid_meeting_request(text,text,text,bigint,text,text,text,bigint,bigint,integer,jsonb,public.recurrence_type,date,text,text) to anon,authenticated;
grant execute on function public.admin_update_paid_offering(bigint,text,text,jsonb,numeric,numeric,numeric) to authenticated;

commit;
